META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–3: ಅನುಭವ ಸಹಿತ ಪೂರ್ಣ ಜ್ಞಾನ, ಮತ್ತು ಅದನ್ನು ಪಡೆಯುವವರು ಎಷ್ಟು ಕಡಿಮೆ; 4–7: ಭಗವಂತನ ಎರಡು ಪ್ರಕೃತಿಗಳು, ಅಪರಾ ಮತ್ತು ಪರಾ; 8–12: ನೀರಿನಲ್ಲಿ ರುಚಿ, ಸೂರ್ಯಚಂದ್ರರಲ್ಲಿ ಬೆಳಕು: ಎಲ್ಲದರಲ್ಲೂ ಭಗವಂತ; 13–15: ಮೂರು ಗುಣಗಳ ಮಾಯೆ, ಅದನ್ನು ಯಾರು ದಾಟುತ್ತಾರೆ; 16–19: ನಾಲ್ಕು ಬಗೆಯ ಭಕ್ತರು, ಜ್ಞಾನಿ ಏಕೆ ಅತ್ಯಂತ ಪ್ರಿಯ; 20–23: ಇತರ ದೇವತೆಗಳ ಉಪಾಸನೆ ಮತ್ತು ಅದರ ಫಲ; 24–30: ಜನ್ಮರಹಿತ ಭಗವಂತನನ್ನು ಜನರು ಏಕೆ ಗುರುತಿಸುವುದಿಲ್ಲ, ಮರಣ ಸಮಯದಲ್ಲೂ ಅವನನ್ನು ಯಾರು ತಿಳಿಯುತ್ತಾರೆ.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಪಾರ್ಥ, ನನ್ನಲ್ಲಿ ಮನಸ್ಸಿಟ್ಟು, ನನ್ನ ಆಶ್ರಯ ಪಡೆದು ಯೋಗವನ್ನು ಅಭ್ಯಾಸ ಮಾಡುತ್ತಾ, ನೀನು ನನ್ನನ್ನು ಸಂಶಯವಿಲ್ಲದೆ ಪೂರ್ಣವಾಗಿ ಹೇಗೆ ತಿಳಿಯುತ್ತೀಯೋ ಅದನ್ನು ಕೇಳು.',
2: 'ಈ ಜ್ಞಾನವನ್ನು ಅದರ ಅನುಭವ ಸಹಿತ ನಿನಗೆ ಪೂರ್ಣವಾಗಿ ಹೇಳುತ್ತೇನೆ. ಇದನ್ನು ತಿಳಿದ ಮೇಲೆ ಈ ಲೋಕದಲ್ಲಿ ತಿಳಿಯಬೇಕಾದ್ದು ಬೇರೇನೂ ಉಳಿಯುವುದಿಲ್ಲ.',
3: 'ಸಾವಿರಾರು ಮನುಷ್ಯರಲ್ಲಿ ಯಾರೋ ಒಬ್ಬರು ಸಿದ್ಧಿಗಾಗಿ ಪ್ರಯತ್ನಿಸುತ್ತಾರೆ. ಪ್ರಯತ್ನಿಸಿ ಸಿದ್ಧರಾದವರಲ್ಲೂ ಯಾರೋ ಒಬ್ಬರು ಮಾತ್ರ ನನ್ನನ್ನು ನಾನಿರುವಂತೆ ನಿಜವಾಗಿ ತಿಳಿಯುತ್ತಾರೆ.',
4: 'ಭೂಮಿ, ನೀರು, ಬೆಂಕಿ, ಗಾಳಿ, ಆಕಾಶ, ಮನಸ್ಸು, ಬುದ್ಧಿ ಮತ್ತು ಅಹಂಕಾರ: ಹೀಗೆ ನನ್ನ ಪ್ರಕೃತಿ ಎಂಟು ಭಾಗಗಳಾಗಿ ವಿಭಾಗವಾಗಿದೆ.',
5: 'ಹೇ ಮಹಾಬಾಹು, ಇದು ನನ್ನ ಅಪರಾ (ಕೆಳಗಿನ) ಪ್ರಕೃತಿ. ಇದಕ್ಕಿಂತ ಬೇರೆಯಾದ ನನ್ನ ಪರಾ (ಉನ್ನತ) ಪ್ರಕೃತಿಯನ್ನು ತಿಳಿ. ಅದೇ ಎಲ್ಲ ಜೀವಿಗಳ ಜೀವ, ಅದೇ ಈ ಜಗತ್ತನ್ನು ಧರಿಸಿದೆ.',
6: 'ಎಲ್ಲ ಜೀವಿಗಳೂ ಈ ಎರಡು ಪ್ರಕೃತಿಗಳಿಂದಲೇ ಹುಟ್ಟುತ್ತವೆ ಎಂದು ತಿಳಿ. ಇಡೀ ಜಗತ್ತಿನ ಉತ್ಪತ್ತಿಯೂ ನಾನೇ, ಅದರ ಲಯವೂ ನಾನೇ.',
8: 'ಹೇ ಕೌಂತೇಯ, ನೀರಿನಲ್ಲಿ ರುಚಿ ನಾನು, ಚಂದ್ರಸೂರ್ಯರಲ್ಲಿ ಬೆಳಕು ನಾನು, ಎಲ್ಲ ವೇದಗಳಲ್ಲಿ ಓಂಕಾರ, ಆಕಾಶದಲ್ಲಿ ಶಬ್ದ ಮತ್ತು ಮನುಷ್ಯರಲ್ಲಿ ಪೌರುಷ ನಾನು.',
9: 'ಭೂಮಿಯಲ್ಲಿ ಪವಿತ್ರ ಸುಗಂಧ ಮತ್ತು ಬೆಂಕಿಯಲ್ಲಿ ತೇಜಸ್ಸು ನಾನು. ಎಲ್ಲ ಜೀವಿಗಳಲ್ಲಿ ಜೀವ ಮತ್ತು ತಪಸ್ವಿಗಳಲ್ಲಿ ತಪಸ್ಸು ನಾನು.',
10: 'ಹೇ ಪಾರ್ಥ, ನನ್ನನ್ನು ಎಲ್ಲ ಜೀವಿಗಳ ಸನಾತನ ಬೀಜ ಎಂದು ತಿಳಿ. ಬುದ್ಧಿವಂತರ ಬುದ್ಧಿ ಮತ್ತು ತೇಜಸ್ವಿಗಳ ತೇಜಸ್ಸು ನಾನು.',
11: 'ಹೇ ಭರತಶ್ರೇಷ್ಠ, ಬಲಶಾಲಿಗಳಲ್ಲಿ ಕಾಮನೆ ಮತ್ತು ಆಸಕ್ತಿ ಇಲ್ಲದ ಬಲ ನಾನು. ಜೀವಿಗಳಲ್ಲಿ ಧರ್ಮಕ್ಕೆ ವಿರುದ್ಧವಲ್ಲದ ಕಾಮನೆ ನಾನು.',
12: 'ಸತ್ತ್ವ, ರಜಸ್ ಮತ್ತು ತಮಸ್ಸಿನಿಂದ ಹುಟ್ಟುವ ಭಾವಗಳೆಲ್ಲವೂ ನನ್ನಿಂದಲೇ ಹುಟ್ಟಿವೆ ಎಂದು ತಿಳಿ. ಆದರೆ ನಾನು ಅವುಗಳಲ್ಲಿಲ್ಲ, ಅವು ನನ್ನಲ್ಲಿವೆ.',
13: 'ಗುಣಗಳಿಂದಾದ ಈ ಮೂರು ಬಗೆಯ ಭಾವಗಳಿಂದ ಇಡೀ ಜಗತ್ತು ಮೋಹಗೊಂಡಿದೆ. ಆದ್ದರಿಂದ ಇವುಗಳಿಗೆ ಅತೀತನಾದ, ಅವಿನಾಶಿಯಾದ ನನ್ನನ್ನು ಅದು ಗುರುತಿಸುವುದಿಲ್ಲ.',
14: 'ಮೂರು ಗುಣಗಳಿಂದ ಕೂಡಿದ ನನ್ನ ಈ ದೈವೀ ಮಾಯೆಯನ್ನು ದಾಟುವುದು ಬಹಳ ಕಷ್ಟ. ಆದರೆ ನನ್ನನ್ನೇ ಶರಣು ಬಂದವರು ಈ ಮಾಯೆಯನ್ನು ದಾಟುತ್ತಾರೆ.',
15: 'ಕೆಟ್ಟ ಕೆಲಸ ಮಾಡುವವರು, ಮೋಹಗೊಂಡವರು, ಮನುಷ್ಯರಲ್ಲಿ ಅಧಮರು ನನ್ನನ್ನು ಶರಣು ಬರುವುದಿಲ್ಲ. ಮಾಯೆ ಅವರ ಜ್ಞಾನವನ್ನು ಅಪಹರಿಸಿದೆ; ಅವರು ಆಸುರೀ ಸ್ವಭಾವವನ್ನು ಆಶ್ರಯಿಸಿದ್ದಾರೆ.',
17: 'ಇವರಲ್ಲಿ ಜ್ಞಾನಿ ಶ್ರೇಷ್ಠ. ಅವನು ಸದಾ ನನ್ನಲ್ಲಿ ತೊಡಗಿ, ನನ್ನಲ್ಲೇ ಭಕ್ತಿ ಇಡುತ್ತಾನೆ. ಜ್ಞಾನಿಗೆ ನಾನು ಅತ್ಯಂತ ಪ್ರಿಯ, ಅವನು ನನಗೆ ಪ್ರಿಯ.',
18: 'ಇವರೆಲ್ಲರೂ ಉದಾರರೇ. ಆದರೆ ಜ್ಞಾನಿಯನ್ನು ನಾನು ನನ್ನ ಸ್ವರೂಪವೆಂದೇ ಭಾವಿಸುತ್ತೇನೆ, ಏಕೆಂದರೆ ಸ್ಥಿರ ಮನಸ್ಸಿನ ಅವನು ನನ್ನನ್ನೇ ಅತ್ಯುನ್ನತ ಗುರಿಯಾಗಿ ಭಾವಿಸಿ ನನ್ನಲ್ಲೇ ನೆಲೆಸಿರುತ್ತಾನೆ.',
19: 'ಅನೇಕ ಜನ್ಮಗಳ ಕೊನೆಯಲ್ಲಿ, "ವಾಸುದೇವನೇ ಎಲ್ಲವೂ" ಎಂದು ತಿಳಿದು ಜ್ಞಾನಿ ನನ್ನನ್ನು ಶರಣು ಬರುತ್ತಾನೆ. ಅಂಥ ಮಹಾತ್ಮ ಬಹಳ ಅಪರೂಪ.',
20: 'ಬಗೆಬಗೆಯ ಕಾಮನೆಗಳಿಂದ ಜ್ಞಾನ ಅಪಹರಿಸಲ್ಪಟ್ಟವರು ತಮ್ಮ ಸ್ವಭಾವದ ಪ್ರೇರಣೆಯಿಂದ, ಬೇರೆ ಬೇರೆ ನಿಯಮಗಳನ್ನು ಪಾಲಿಸುತ್ತಾ ಇತರ ದೇವತೆಗಳನ್ನು ಶರಣು ಹೋಗುತ್ತಾರೆ.',
21: 'ಯಾವ ಭಕ್ತ ಯಾವ ರೂಪವನ್ನು ಶ್ರದ್ಧೆಯಿಂದ ಪೂಜಿಸಲು ಬಯಸುತ್ತಾನೋ, ಆ ಭಕ್ತನಿಗೆ ಆ ರೂಪದ ಮೇಲಿನ ಶ್ರದ್ಧೆಯನ್ನು ನಾನು ಸ್ಥಿರಗೊಳಿಸುತ್ತೇನೆ.',
22: 'ಆ ಶ್ರದ್ಧೆಯಿಂದ ಅವನು ಆ ರೂಪವನ್ನು ಆರಾಧಿಸಿ, ಅದರ ಮೂಲಕ ತಾನು ಬಯಸಿದ್ದನ್ನು ಪಡೆಯುತ್ತಾನೆ. ಆದರೆ ಆ ಫಲಗಳನ್ನು ನಿಜವಾಗಿ ಕೊಡುವವನು ನಾನೇ.',
23: 'ಆದರೆ ಅಲ್ಪಬುದ್ಧಿಯ ಇವರಿಗೆ ಸಿಗುವ ಫಲ ನಾಶವಾಗುವಂಥದ್ದು. ದೇವತೆಗಳನ್ನು ಪೂಜಿಸುವವರು ದೇವತೆಗಳನ್ನು ಸೇರುತ್ತಾರೆ, ನನ್ನ ಭಕ್ತರು ನನ್ನನ್ನು ಸೇರುತ್ತಾರೆ.',
24: 'ಬುದ್ಧಿಹೀನರು ಅವ್ಯಕ್ತನಾದ ನನ್ನನ್ನು ಸಾಮಾನ್ಯ ರೂಪ ಧರಿಸಿದವನೆಂದು ಭಾವಿಸುತ್ತಾರೆ. ಅವಿನಾಶಿಯಾದ, ಸರ್ವೋತ್ತಮವಾದ ನನ್ನ ಪರಮ ಭಾವವನ್ನು ಅವರು ತಿಳಿಯರು.',
25: 'ನನ್ನ ಯೋಗಮಾಯೆಯಿಂದ ಮುಚ್ಚಿಕೊಂಡಿರುವ ನಾನು ಎಲ್ಲರಿಗೂ ಕಾಣಿಸುವುದಿಲ್ಲ. ಮೋಹಗೊಂಡ ಈ ಲೋಕ ಜನ್ಮರಹಿತನಾದ, ಅವಿನಾಶಿಯಾದ ನನ್ನನ್ನು ಗುರುತಿಸುವುದಿಲ್ಲ.',
26: 'ಹೇ ಅರ್ಜುನ, ಕಳೆದುಹೋದ, ಈಗಿರುವ ಮತ್ತು ಮುಂದೆ ಬರುವ ಜೀವಿಗಳನ್ನು ನಾನು ತಿಳಿದಿದ್ದೇನೆ; ಆದರೆ ನನ್ನನ್ನು ಯಾರೂ ತಿಳಿಯರು.',
27: 'ಹೇ ಭಾರತ, ಹೇ ಪರಂತಪ, ಬಯಕೆ ಮತ್ತು ದ್ವೇಷದಿಂದ ಹುಟ್ಟುವ ಸುಖ-ದುಃಖದಂತಹ ದ್ವಂದ್ವಗಳ ಮೋಹದಿಂದ ಎಲ್ಲ ಜೀವಿಗಳೂ ಹುಟ್ಟುವಾಗಲೇ ಭ್ರಮೆಗೆ ಒಳಗಾಗುತ್ತವೆ.',
28: 'ಆದರೆ ಪುಣ್ಯಕರ್ಮಗಳಿಂದ ಪಾಪ ನಾಶವಾದವರು ದ್ವಂದ್ವಮೋಹದಿಂದ ಮುಕ್ತರಾಗಿ, ದೃಢನಿಶ್ಚಯದಿಂದ ನನ್ನನ್ನು ಭಜಿಸುತ್ತಾರೆ.',
29: 'ನನ್ನ ಆಶ್ರಯ ಪಡೆದು ಮುಪ್ಪು ಮತ್ತು ಮರಣದಿಂದ ಮುಕ್ತಿಗಾಗಿ ಪ್ರಯತ್ನಿಸುವವರು ಆ ಬ್ರಹ್ಮವನ್ನು, ಸಂಪೂರ್ಣ ಅಧ್ಯಾತ್ಮವನ್ನು ಮತ್ತು ಸಮಸ್ತ ಕರ್ಮವನ್ನು ತಿಳಿಯುತ್ತಾರೆ.',
30: 'ಅಧಿಭೂತ (ಎಲ್ಲ ಭೂತಗಳ ಆಧಾರ), ಅಧಿದೈವ (ದೇವತೆಗಳ ಆಧಾರ) ಮತ್ತು ಅಧಿಯಜ್ಞ (ಎಲ್ಲ ಯಜ್ಞಗಳ ಆಧಾರ) ಸಹಿತ ನನ್ನನ್ನು ತಿಳಿಯುವವರು, ಸ್ಥಿರ ಮನಸ್ಸಿನಿಂದ ಮರಣ ಸಮಯದಲ್ಲೂ ನನ್ನನ್ನು ತಿಳಿಯುತ್ತಾರೆ.',
}
